input.new_string:
def _is_valid_expected_value(value) -> bool:
    """expected_value 是否合法：标量、仅含标量的一维数组，或仅含标量成员的对象。

    空数组与空对象均合法；数组元素与对象成员可混合字符串、布尔、有限数字与
    null，但不能是对象或数组（对象只接受一层，不接受嵌套对象，也不接受
    数组成员），也不能含 NaN/Infinity/1e400 等非有限数字。
    """
    if isinstance(value, list):
        return all(_is_scalar_expected_value(item) for item in value)
    if isinstance(value, dict):
        # JSON 对象的键经解析后一律为字符串；只需限制成员值：
        # 每个成员都必须是标量，嵌套对象与数组在此被拒绝（空对象天然合法）。
        return all(
            _is_scalar_expected_value(item) for item in value.values()
        )
    return _is_scalar_expected_value(value)

